class _EmbeddedSrcLoader(_importlib_abc.MetaPathFinder, _importlib_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname in _EMBEDDED_MODULES:
            return _importlib_util.spec_from_loader(
                fullname, self, is_package=(fullname == "src")
            )
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        fullname = module.__spec__.name
        source = _zlib.decompress(
            _b64.b64decode(_EMBEDDED_MODULES[fullname])
        ).decode("utf-8")
        if fullname == "src":
            module.__path__ = [str(_EMBED_ROOT / "src")]
            module.__package__ = "src"
            module.__file__ = str(_EMBED_ROOT / "src" / "__init__.py")
        else:
            stem = fullname.rsplit(".", 1)[-1]
            module.__package__ = fullname.rsplit(".", 1)[0]
            module.__file__ = str(_EMBED_ROOT / "src" / f"{stem}.py")
        exec(compile(source, module.__file__, "exec"), module.__dict__)

