def number_with_unit(label: str, key: str, unit: str, help_text: str, min_value: float, max_value: float, step: float, fmt: str) -> None:
    """Render a physical input with its symbol meaning and unit visible beside it."""
    definition = INPUT_SYMBOLS.get(key)
    st.markdown(f"**{label}**")
    c1, c2 = st.columns([11, 1], vertical_alignment="bottom")
    with c1:
        st.number_input(
            label,
            key=key,
            min_value=min_value,
            max_value=max_value,
            step=step,
            format=fmt,
            help=help_text,
            label_visibility="collapsed",
        )
    with c2:
        st.markdown(f'<div class="unit-cell">{unit}</div>', unsafe_allow_html=True)
    if definition is not None:
        st.caption(f"{definition.symbol} = {definition.meaning} · Unit: {definition.unit}. {definition.note}")
    else:
        st.caption(f"Meaning: {help_text} · Unit: {unit}.")


def axis_label(axis: np.ndarray) -> str:
    v = np.asarray(axis, float)
    nz = np.abs(v[np.abs(v) > 1e-8])
    if len(nz):
        w = np.rint(v / np.min(nz)).astype(int)
        for x in w:
            if x != 0:
                if x < 0:
                    w *= -1
                break
        return "[" + " ".join(str(int(x)) for x in w) + "]"
    return "[0 0 0]"


def domain_spec_label(spec: CofactorDomainSpec) -> str:
    if spec.partner_axis is None:
        return f"{spec.domain_type} · ê={axis_label(spec.axis)}"
    return f"{spec.domain_type} · ê={axis_label(spec.axis)} · partner={axis_label(spec.partner_axis)}"


def plane_text(p: np.ndarray) -> str:
    return "(" + ", ".join(f"{x:.5f}" for x in p) + ")"


def pct(x: float) -> str:
    return f"{100*x:.1f}%"


def render_symbol_definitions(definitions: list[SymbolDefinition] | tuple[SymbolDefinition, ...], *, heading: str = "What every symbol means") -> None:
    """Show notation immediately next to a formula/result; never rely on assumed knowledge."""
    defs = list(definitions)
    if not defs:
        return
    st.markdown(f"**{heading}**")
    cols = st.columns(2) if len(defs) > 1 else [st.container()]
    for idx, definition in enumerate(defs):
        target = cols[idx % len(cols)]
        with target:
            note = f" · {definition.note}" if definition.note else ""
            st.markdown(f"- **${definition.symbol}$** = {definition.meaning}  \n  **Unit/scale:** {definition.unit}{note}")


def explained_metric(container, label: str, value, definition: SymbolDefinition | str, *, delta=None, help_text: str | None = None) -> None:
    """Metric card followed immediately by a plain-language definition."""
    container.metric(label, value, delta=delta, help=help_text)
    if isinstance(definition, SymbolDefinition):
        note = f" {definition.note}" if definition.note else ""
        container.caption(f"{definition.symbol} = {definition.meaning}. Unit/scale: {definition.unit}.{note}")
    else:
        container.caption(definition)


def formula_with_symbols(latex: str, definitions: list[SymbolDefinition] | tuple[SymbolDefinition, ...], *, heading: str = "What every symbol means") -> None:
    st.latex(latex)
    render_symbol_definitions(definitions, heading=heading)
    render_symbol_definitions(operators_for_latex(latex), heading="Operators and notation in this relation")


def math_used(keys: list[str] | tuple[str, ...], title: str = "Math used — relation, source, implementation") -> None:
    """Expose equation-level provenance next to a numerical result."""
    reg = equation_registry()
    with st.expander(title):
        st.caption("Every listed result is tied to a named relation, a source or extension class, the code path that evaluates it, and an explicit scope/caveat.")
        for key in keys:
            eq = reg.get(key)
            if eq is None:
                st.warning(f"Equation key `{key}` is not registered in this build.")
                continue
            st.markdown(f"**{eq.key} · {eq.topic}**")
            st.latex(eq.relation_latex)
            render_symbol_definitions(definitions_for_equation(key))
            render_symbol_definitions(operators_for_latex(eq.relation_latex), heading="Operators and notation in this relation")
            st.caption(f"{eq.provenance_class} · {eq.source_location}")
            st.write(eq.meaning)
            st.caption(f"Implementation: `{eq.implementation}` · Scope: {eq.scope}")
            if eq.caveat:
                st.warning(eq.caveat)


